WITH filtered_payments AS (SELECT *, CASE WHEN method IN ('cash', 'paypal') THEN 'Tier 1' ELSE 'Other' END AS method_group FROM payments WHERE status != 'SUCCESS'), agg AS (SELECT status, MONTH(paid_at) AS paid_month, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(*) AS total_count FROM filtered_payments GROUP BY status, MONTH(paid_at)) SELECT * FROM agg ORDER BY total_count ASC, status ASC
